actions.script:
generatedStr = ec.l10n.format(ec.user.nowTimestamp, 'dd MMM yyyy HH:mm')
def _org = ec.user.getPreference("ACTIVE_ORGANIZATION")
def f = ec.entity.find("zenith.erp.pos.PosAmendmentView")
if (_org && _org != '_NA_') f.condition("organizationPartyId", _org)
if (fromDate) f.condition("amendmentDate", "greater-equals", java.sql.Timestamp.valueOf(fromDate + ' 00:00:00'))
if (thruDate) f.condition("amendmentDate", "less-equals", java.sql.Timestamp.valueOf(thruDate + ' 23:59:59'))
if (changeType) f.condition("changeType", changeType)
if (changedBy) f.condition("amendedByPartyId", changedBy)
f.orderBy("-amendmentDate")
def all = f.list()
def stx = (searchText ?: '').trim().toLowerCase()
if (stx) all = all.findAll { r -> def nm = "${r.firstName ?: ''} ${r.lastName ?: ''}".toString();
    [r.transactionNumber, r.productName, r.reason, nm, r.amendedByPartyId, r.oldValue, r.newValue]
        .collect { (it ?: '').toString().toLowerCase() }.any { it.contains(stx) } }
periodStr = ((fromDate ?: 'all') + ' to ' + (thruDate ?: 'now'))
rowCountStr = all.size().toString()
def dtf = { v -> v == null ? '' : ec.l10n.format(v, 'dd-MM-yyyy HH:mm') }
// XSL-FO is XML: escape &, <, > in free-text values
def x = { v -> (v ?: '').toString().replace('&','&amp;').replace('<','&lt;').replace('>','&gt;') }
def who = { r -> def nm = "${r.firstName ?: ''} ${r.lastName ?: ''}".toString().trim(); nm ?: (r.amendedByPartyId ?: '') }
rows = all.collect { r ->
    [dt:x(dtf(r.amendmentDate)), bill:x(r.transactionNumber), type:x(r.changeType), product:x(r.productName),
     oldv:x(r.oldValue), newv:x(r.newValue), who:x(who(r)), term:x(r.terminalName), reason:x(r.reason)] }
